function toHexDigits(num: number): string {
  if (num === 0) return "0";
  const DIGITS = "0123456789abcdef";
  let v = num < 0 ? num + 4294967296 : num;
  const out: string[] = [];
  while (v > 0) {
    out.push(DIGITS[v % 16]);
    v = Math.floor(v / 16);
  }
  return out.reverse().join("");
}

