class Solution:
    def toHexDigits(self, num: int) -> str:
        if num == 0:
            return "0"
        digits = "0123456789abcdef"
        v = num + (1 << 32) if num < 0 else num
        out = []
        while v > 0:
            out.append(digits[v % 16])
            v //= 16
        return "".join(reversed(out))

