function toHexDigits(num: number): string {
  if (num === 0) return "0";
  const DIGITS = "0123456789abcdef";
  let v = num >>> 0; // 32-bit unsigned view
  let out = "";
  while (v !== 0) {
    out = DIGITS[v & 15] + out;
    v >>>= 4;
  }
  return out;
}

